SELECT COUNT(*) FROM quant_live_account_settings_intent
WHERE credential_id=#{credentialId} AND symbol=#{symbol}
  AND margin_mode=#{marginMode} AND leverage=#{leverage}

mapper.update:
UPDATE quant_live_dispatch_guard
SET active_dispatch_key=#{key}, updated_at=UTC_TIMESTAMP()
WHERE credential_id=#{credentialId} AND symbol=#{symbol}
  AND active_dispatch_key IS NULL
  AND EXISTS (
      SELECT 1 FROM quant_strategy_runtime_lease l
      WHERE l.credential_id=#{credentialId} AND l.symbol=#{symbol}
        AND l.instance_id=#{instanceId} AND l.lease_epoch=#{epoch}
        AND l.lease_until>NOW() AND l.owner_token IS NOT NULL
  )

mapper.insert:
INSERT INTO quant_strategy_pre_dispatch_intent
(credential_id,symbol,idempotency_key,client_order_id,strategy_id,
 strategy_instance_id,operation_type,position_side,exchange_side,position_cycle_key,
 lease_epoch,created_at)
SELECT #{credentialId},#{symbol},#{key},#{clientOrderId},#{strategyId},
       #{instanceId},#{operation},#{positionSide},#{exchangeSide},s.position_cycle_key,
       #{epoch},UTC_TIMESTAMP(6)
FROM quant_strategy_position_state s
JOIN quant_strategy_instance i ON i.id=s.instance_id AND i.credential_id=#{credentialId}
JOIN quant_strategy_symbol ss ON ss.id=i.strategy_symbol_id
JOIN quant_symbol q ON q.id=ss.symbol_id AND q.symbol=#{symbol}
WHERE s.instance_id=#{instanceId}
  AND s.position_cycle_key IS NOT NULL
  AND s.direction=#{positionSide}
  AND s.pending_idempotency_key=#{key}
  AND s.status IN ('OPEN_PENDING','OPEN','EXIT_PENDING')

mapper.update:
UPDATE quant_order_dispatch_ticket
SET dispatch_status='RECOVERED', updated_at=UTC_TIMESTAMP()
WHERE credential_id=#{credentialId} AND idempotency_key=#{key}
  AND symbol=#{symbol} AND client_order_id=#{clientOrderId}
  AND operation_type='CONFIG_SETTINGS' AND exchange_order_id IS NULL
  AND dispatch_status='CONFIG_APPLIED'
  AND EXISTS (
    SELECT 1 FROM quant_live_dispatch_guard g
    WHERE g.credential_id=#{credentialId} AND g.symbol=#{symbol}
      AND g.active_dispatch_key=#{key}
  )
  AND EXISTS (
    SELECT 1 FROM quant_live_account_settings_intent i
    WHERE i.credential_id=#{credentialId} AND i.symbol=#{symbol}
      AND i.margin_mode=#{marginMode} AND i.leverage=#{leverage}
  )

UPDATE quant_live_dispatch_guard SET active_dispatch_key=NULL, updated_at=UTC_TIMESTAMP()
WHERE credential_id=#{credentialId} AND symbol=#{symbol}
  AND active_dispatch_key=#{key}

UPDATE quant_order_dispatch_ticket
SET dispatch_status='RECOVERED', exchange_order_id=#{orderId}, updated_at=UTC_TIMESTAMP()
WHERE credential_id=#{credentialId} AND idempotency_key=#{key}
  AND symbol=#{symbol} AND client_order_id=#{clientOrderId}
  AND (exchange_order_id IS NULL OR exchange_order_id=#{orderId})
  AND dispatch_status IN ('DISPATCHING','UNKNOWN')
  AND EXISTS (
    SELECT 1 FROM quant_live_dispatch_guard g
    WHERE g.credential_id=#{credentialId} AND g.symbol=#{symbol}
      AND g.active_dispatch_key=#{key}
  )
